@app.post('/api/allowlist/request')
async def allowlist_request(request: Request):
    # Agent-facing request to extend the player-vetted allowlist.
    # An allowlist entry means FULL read+write reachability for sandboxed
    # scripts AND it skips every future Jev classify round trip -- a permanent
    # capability grant, because a worker can only get one through an
    # explicit human approval, so this fires a floor-1.0 escalation that ONLY
    # the player's email link can resolve (the director is never permitted to
    # auto-approve it). Agents call this instead of editing .env; when the
    # player approves, the host is granted to the runtime allowlist and the
    # egress proxy is refreshed so already-running scripts can reach it too.
    body = await request.json()
    agent_id = (body.get('agentId') or 'unknown')
    target = (body.get('host') or body.get('url') or '').strip()
    purpose = (body.get('purpose') or '').strip()
    if not check_rate_limit(agent_id):
        log_action(agent_id, 'rate_limited', {'endpoint': 'allowlist_request'})
        return JSONResponse({'error': f'Rate limit exceeded -- max {RATE_LIMIT_MAX_CALLS} calls per {RATE_LIMIT_WINDOW_S}s.'}, status_code=429)
    authorized = verify_agent_key(agent_id, request.headers.get('X-Agent-Key'))
    if not target:
        return JSONResponse({'error': 'a host or url is required'}, status_code=400)
    # Normalize a full URL down to its hostname, a bare host is acceptable.
    parsed = urllib.parse.urlparse(target if '://' in target else 'https://' + target)
    host = (parsed.hostname or '').strip().lower()
    if not host:
        return JSONResponse({'error': 'could not read a hostname from that target'}, status_code=400)
    # Same boundary as every other gate: private/internal targets are refused
    # outright -- the allowlist extends PUBLIC reachability, never SSRF surface.
    if not _is_safe_public_host(host):
        return JSONResponse({'error': f'{host} is a private or internal host and can never be allowlisted'}, status_code=400)
    if _is_allowlisted_host(host):
        return JSONResponse({'allowlisted': True, 'host': host,
                             'message': 'already on the allowlist -- new requests are not needed'})
    # One pending request per host at a time -- no escalation spam from the
    # same agent retrying a request that's already waiting on the player.
    for esc_id, esc in _load_escalations().items():
        if esc.get('kind') == 'allowlist request' and esc.get('status') == 'pending' \
                and esc.get('note', '').strip().lower() == host:
            return JSONResponse({'requested': True, 'host': host, 'escalationId': esc_id,
                                 'message': 'an allowlist request for this host is already pending review'})
    esc_id = create_escalation(
        'allowlist request',
        f'Agent {agent_id} requests {host} be added to the player-vetted allowlist.\n'
        f'Stated purpose: {purpose or "not given"}\n\n'
        f'Approving gives agents standing read+write reachability to {host} for sandboxed '
        f'scripts, AND lets them reach it without a Jev classify round trip on every call. '
        f'Only the player can approve or deny this -- the director is not allowed to.',
        on_approve_note=host,
    )
    log_action(agent_id, 'allowlist_request', {'host': host, 'purpose': purpose[:200],
                                               'escalationId': esc_id}, authorized=authorized)
    return JSONResponse({'requested': True, 'host': host, 'escalationId': esc_id,
                         'message': f'Allowlist request for {host} filed -- the player decides by email; '
                                    f'until then {host} still goes through the normal Jev gate.'})


CURL_METHODS = {'GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD'}
CURL_MAX_BODY_BYTES = 200_000
CURL_TIMEOUT_S = 15

# An agent without standing access to something
# (e.g. an agent with no Weather Station curl access) should be able to
# ask their supervisor for it and get REAL, TEMPORARY access if the reason
# is legitimate -- a real, gated, expiring exception layered on top of the
# existing room check, not a way around it. Starts
# with curl; the mechanism generalizes to
# any future room/role-gated capability by just adding it here.
TEMP_ACCESS_CAPABILITIES = {
    'curl': 'Real HTTP requests to the open internet -- normally restricted to inside the Weather Station.',
    'sandbox-download': 'Downloading a file directly into a sandbox -- normally restricted to inside the Work Room or the Observatory.',
}
# Long enough to actually finish one real task, short enough that this is
# genuinely temporary rather than a backdoor standing grant.
TEMP_ACCESS_DURATION_S = 1200


def _has_active_temp_access(agent_id, capability):
    with _db() as conn:
        row = conn.execute(
            'SELECT expires_at FROM temp_access_grants WHERE agent_id = ? AND capability = ?',
            (agent_id, capability),
        ).fetchone()
    # NULL expires_at = a story-scoped grant: no timer, active until its story
    # ships (revoke_task_access on completion). Anything else must still be
    # inside its window.
    return bool(row and (row[0] is None or row[0] > time.time()))


def _grant_temp_access(agent_id, capability, granted_by, reason, task_id=None):
    now = time.time()
    # A story-scoped grant rides NO clock: it lives until the story it was
    # granted for ships (revoke_task_access on completion). Only a grant with
    # no story keeps the finite window, so nothing is ever permanent.
    expires_at = None if task_id else now + TEMP_ACCESS_DURATION_S
    with _db() as conn:
        conn.execute(
            'INSERT INTO temp_access_grants (agent_id, capability, granted_by, reason, granted_at, expires_at, task_id) VALUES (?, ?, ?, ?, ?, ?, ?) '
            'ON CONFLICT(agent_id, capability) DO UPDATE SET granted_by=excluded.granted_by, reason=excluded.reason, granted_at=excluded.granted_at, expires_at=excluded.expires_at, task_id=excluded.task_id',
            (agent_id, capability, granted_by, reason, now, expires_at, task_id),
        )
    return expires_at


def revoke_task_access(task_id):
    """Per-story capability grant lifecycle: a temp grant is tied to the SPECIFIC
    story it was granted for (task_id), so the moment that story ships the grant
    dies with it -- capability access never outlives the work that justified it.
    Best-effort (a missing DB must never break a completion path)."""
    if not task_id:
        return
    try:
        with _db() as conn:
            conn.execute('DELETE FROM temp_access_grants WHERE task_id = ?', (task_id,))
    except Exception:
        pass


def _agent_is_in_weatherstation(agent_id, live_room=None):
    # Real server-side room gate: curl only
    # from the Weather Station, same exclusivity Eli's own profile already
    # states for outside/internet access generally (Studio's screenshot-
    # based visual research is the one other exception, and that goes
    # through /api/browse's existing Jev gate, not this raw-HTTP one).
    # Checked against the real persisted state (autosaved every 5s), not
    # trusted from whatever the client claims in the request -- a client
    # could lie about its own location, but it can't rewrite what was
    # already saved to the server's own database.
    #
    # Race fixed: an agent's `inRoom` is
    # maintained in the browser in real-time but only persisted to the DB
    # on the client's 5s autosave. So an agent arriving in the Weather
    # Station and making its very first curl call within those 5 seconds
    # could have `inRoom: 'weatherstation'` live but not yet autosaved --
    # and this gate, reading the stale saved state, would wrongly deny a
    # legitimate in-room request. The fix: accept the calling client's
    # LIVE assertion of the agent's current room (`live_room`, passed in
    # the request body) as an override, validated against the exact room
    # that grants this capability. The client is the origin of all
    # position truth anyway (agents move in the browser); this just closes
    # the autosave-latency gap. The claimed room must still be the one
    # real eligible room -- an agent can't assert an arbitrary room to
    # unlock a capability.
    #
    # 'player' is a real exception, not a loophole: the human player has
    # no `inRoom` entry at all (that field only exists for NPC agents), so
    # this would otherwise ALWAYS block the player even when standing
    # right in the Weather Station -- which is the only way this UI is
    # ever reachable in the first place (openTerminal()'s own room gate,
    # index.html). Every other identity still gets the real check.
    if agent_id == 'player':
        return True
    # live_room override first -- it's the freshest truth an agent has.
    if live_room == 'weatherstation':
        return True
    state = get_state_from_db()
    if not state:
        return False
    agent = (state.get('agents') or {}).get(agent_id)
    return bool(agent and agent.get('inRoom') == 'weatherstation')


SANDBOX_DOWNLOAD_ROOMS = ('observatory', 'pressoffice')


def _agent_is_in_sandbox_room(agent_id, live_room=None):
    # Real server-side room gate, extended to
    # the Work Room: downloading directly into a sandbox
    # only works from inside a room that actually has one -- Observatory
    # (RESEARCH_SANDBOX_ID) or Work Room (WORKROOM_SANDBOX_ID) -- same
    # exclusivity curl draws around the Weather Station
    # (_agent_is_in_weatherstation, right above). Checked against the
    # real persisted state, not trusted from whatever the client claims.
    # `live_room` is the agent's current in-room as asserted by the
    # calling client in real-time -- accepted as the same autosave-latency
    # override described in _agent_is_in_weatherstation (an agent that
    # just arrived hasn't had its `inRoom` autosaved yet, and the very
    # first sandbox call would otherwise be wrongly denied).
    if agent_id == 'player':
        return True
    if live_room in SANDBOX_DOWNLOAD_ROOMS:
        return True
    state = get_state_from_db()
    if not state:
        return False
    agent = (state.get('agents') or {}).get(agent_id)
    return bool(agent and agent.get('inRoom') in SANDBOX_DOWNLOAD_ROOMS)


API_CALL_MAX_BODY_BYTES = 200_000
API_CALL_TIMEOUT_S = 20


def _api_request_sync(method, url, headers, body):
    """Raw outbound HTTP for /api/api-call, mirroring _curl_request_sync's
    redirect re-check (a redirect is exactly how an allowed-looking URL could
    end up pointed at an internal address) and size cap. Returns
    {'status', 'finalUrl', 'contentType', 'body', 'truncated'}."""
    data = json.dumps(body).encode() if (body is not None and method not in ('GET', 'HEAD')) else None
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    if 'User-Agent' not in {k.title() for k in headers}:
        req.add_header('User-Agent', 'AIThinkTankAgent/1.0')
    with _safe_urlopen(req, timeout=API_CALL_TIMEOUT_S) as resp:  # registry/SSRF-gated hosts only; _safe_urlopen pins each resolved IP so DNS cannot rebind to an internal address; re-checked below after redirects
        final_url = resp.geturl()
        final_host = urllib.parse.urlparse(final_url).hostname
        if not _is_safe_public_host(final_host):
            raise ValueError('redirected to a disallowed host')
        raw = resp.read(API_CALL_MAX_BODY_BYTES + 1)
        truncated = len(raw) > API_CALL_MAX_BODY_BYTES
        raw = raw[:API_CALL_MAX_BODY_BYTES]
        return {
            'status': resp.status,
            'finalUrl': final_url,
            'contentType': (resp.headers.get('content-type') or ''),
            'body': raw.decode(errors='replace'),
            'truncated': truncated,
        }


def _api_build_text(result, service, registered, hostname):
    """Turn a raw fetch result into (parsed_json, ctype, wrapped, instruction)
    -- JSON kept structured, HTML stripped to text, else raw; capped,
    truncated, redacted, and always wrapped as untrusted external DATA."""
    body = result['body']
    ctype = (result.get('contentType') or '').lower()
    parsed_json = None
    if 'json' in ctype:
        try:
            parsed_json = json.loads(body)
            text = json.dumps(parsed_json, indent=2, ensure_ascii=False)[:20000]
        except ValueError:
            text = body[:20000]
    elif 'html' in ctype:
        text = _strip_html_to_text(body)[:20000]
    else:
        text = body[:20000]
    text = _redact_secrets(text)
    if result.get('truncated'):
        text += '\n[truncated: response larger than the size cap]'
    wrapped, _nonce, _tag, instruction = wrap_external_content(
        text, f'a {service.get("name", hostname)} API response' if registered else 'an external API response')
    return parsed_json, ctype, wrapped, instruction


def _api_accrue(spend_kind, ctype, parsed_json):
    """Accrue spend from a response per the registry's spend rule. Page-request
    budget for the services that consume it; Apify's real reported cost from
    the run object."""
    kind = (spend_kind or {}).get('kind')
    if kind == 'page_request':
        _accrue_page_request()
    elif kind == 'apify' and isinstance(parsed_json, dict):
        try:
            usage = float(parsed_json.get('usageTotalUsd') or 0)
        except (ValueError, TypeError):
            usage = 0.0
        if usage:
            _accrue_apify_spend(usage)


def _api_workflow_url(base_url, template, values):
    """Substitute {field} placeholders in a workflow path template and join to
    the service base URL. Missing placeholders raise so a misconfigured spec
    fails closed instead of hitting a raw '/{field}' path."""
    formatted = template
    for key, val in (values or {}).items():
        formatted = formatted.replace('{' + key + '}', str(val))
    if '{' in formatted:
        raise ValueError(f'workflow path template still has unresolved placeholders: {template}')
    return base_url.rstrip('/') + ('/' + formatted.lstrip('/') if formatted else '')


def _api_execute_workflow(service, spend_kind, base_url, method, req_headers, req_body, workflow_params, agent_id=None):
    """Run a registered service's multi-step workflow (submit -> poll ->
    optional finalize), with the registry's spend rule applied. This is the
    generic engine behind the higgsfield (image/video) and pixellab
    (character) generation tools -- the bespoke _higgsfield_generate /
    pixellab orchestration is replaced by this config-driven interpreter.
    Returns the same shape as a single _api_execute result, with the final
    artifact's JSON under 'data'."""
    spec = (service or {}).get('workflow') or {}
    values = dict(workflow_params or {})
    req_headers = dict(req_headers or {})

    def _request(path_template, body, method, timeout=API_CALL_TIMEOUT_S):
        url = _api_workflow_url(base_url, path_template, values)
        result = _api_request_sync(method, url, req_headers, body)
        try:
            return json.loads(result['body'])
        except (ValueError, TypeError):
            return None

    # Spend resolution.
    spend = (spec.get('spend') or {})
    spend_service = spend.get('service')
    if spend.get('kind') == 'estimate_first':
        estimate = _request(spec['estimate']['path_template'], req_body, 'POST')
        usd = 0.0
        try:
            usd = float((estimate or {}).get(spec['estimate'].get('usd_field', 'usd')) or 0)
        except (ValueError, TypeError):
            usd = 0.0
    balance_before = None
    if spend.get('kind') == 'balance_delta':
        bal = _request(spend.get('balance_path', '/v2/balance'), None, 'GET')
        balance_before = (bal or {}).get('balance')

    # Submit.
    submit_spec = spec.get('submit') or {}
    submit_path = submit_spec.get('path_template') or '/'
    submit_resp = _request(submit_path, req_body, submit_spec.get('method', 'POST'))
    if not isinstance(submit_resp, dict):
        raise ValueError(f'submit step did not return JSON: {submit_resp}')
    id_field = submit_spec.get('id_field')
    job_id = submit_resp.get(id_field)
    if not job_id:
        raise ValueError(f'submit response missing "{id_field}": {json.dumps(submit_resp)[:300]}')
    values[id_field] = job_id
    for extra in submit_spec.get('extra_ids') or []:
        if submit_resp.get(extra):
            values[extra] = submit_resp[extra]

    # Poll.
    poll_spec = spec.get('poll') or {}
    terminal = set(poll_spec.get('terminal') or ['completed', 'failed'])
    success = set(poll_spec.get('success') or [])
    interval = float(poll_spec.get('interval_s') or 6)
    timeout_s = float(poll_spec.get('timeout_s') or 120)
    poll_path = poll_spec.get('path_template')
    poll_resp = submit_resp
    final_status = (poll_resp or {}).get('status') or 'RUNNING'
    deadline = time.time() + timeout_s
    if poll_path:
        while True:
            poll_resp = _request(poll_path, None, poll_spec.get('method', 'GET')) or {}
            final_status = poll_resp.get('status') or 'RUNNING'
            if final_status in terminal:
                break
            if time.time() >= deadline:
                raise TimeoutError(f'workflow poll timed out after {timeout_s:.0f}s (last status {final_status})')
            time.sleep(interval)

    # Finalize (fetch the artifact once complete).
    finalize_path = ((spec.get('finalize') or {}).get('path_template')) if spec.get('finalize') else None
    final_data = poll_resp
    if finalize_path:
        final_data = _request(finalize_path, None, (spec.get('finalize') or {}).get('method', 'GET')) or {}

    # Accrue spend ONLY on a successful terminal -- a failed/canceled/NSFW
    # generation is never charged (same rule _higgsfield_generate enforced).
    charged = bool(success) and final_status in success
    if charged and spend.get('kind') == 'estimate_first' and usd > 0:
        _accrue_spend(spend_service, usd, agent_id=agent_id)
    elif charged and spend.get('kind') == 'balance_delta':
        bal = _request(spend.get('balance_path', '/v2/balance'), None, 'GET')
        balance_after = (bal or {}).get('balance')
        if isinstance(balance_before, (int, float)) and isinstance(balance_after, (int, float)):
            real_cost = max(0.0, balance_before - balance_after)
            if real_cost > 0:
                _accrue_spend(spend_service, real_cost, agent_id=agent_id)

    return {'data': final_data, 'status': final_status, 'contentType': 'application/json',
            'usd': usd if spend.get('kind') == 'estimate_first' else None, 'ids': values}


def _api_channel_execute(agent_id, agent_key, channel, url, method, req_headers, req_body, purpose, trace_id, _channel_depth=0):
    """Run a channel's ORDERED backend chain: the first backend that answers
    wins; on failure the chain falls through to the next backend (agent-reach's
    per-platform ordered-backends pattern). Each backend is a registered service
    plus a url_template, so each hop re-enters _api_execute against the backend
    URL -- the backend's own path rules, credential, auth injection, SSRF and
    redirect re-check, redaction, and spend accrual all apply. Channels are
    strictly read-only GET/HEAD. Returns an _api_execute-style result dict;
    never raises for a blocked or failed request."""
    if method not in ('GET', 'HEAD'):
        return {'ok': False, 'allowed': False, 'reason': 'Channels are read-only (GET/HEAD only). Use a registered service for writes.'}
    if _channel_depth > 1:
        return {'ok': False, 'allowed': True, 'error': 'Channel backend chain exceeded maximum depth.'}
    errors = []
    for backend in channel.get('backends') or []:
        bservice_id = backend.get('service')
        bservice = _API_SERVICES.get(bservice_id)
        if not bservice:
            errors.append(f'backend {bservice_id} is not a registered service')
            continue
        backend_url = _api_backend_url(backend, url)
        bparsed = urllib.parse.urlparse(backend_url)
        if bparsed.scheme not in ('http', 'https') or not bparsed.hostname:
            errors.append(f'backend {bservice_id}: produced a malformed URL')
            continue
        if not _is_safe_public_host(bparsed.hostname):
            errors.append(f'backend {bservice_id}: resolves to a private or internal network location')
            continue
        out = _api_execute(agent_id, agent_key, backend_url, method, req_headers, req_body,
                           purpose, False, None, trace_id, _channel_depth=_channel_depth + 1)
        if out.get('allowed') is True and out.get('ok') is True:
            out['channel'] = channel.get('name')
            out['backend'] = bservice_id
            out['service'] = f"{channel.get('name')} (via {bservice_id})"
            # The content is the channel target the agent asked for, not the
            # reader transport -- report the original URL so the Jev redirect
            # re-gate (same-host check) treats it as the approved destination.
            out['finalUrl'] = url
            return out
        errors.append(f'backend {bservice_id}: {out.get("error") or out.get("reason") or "request failed"}')
    return {'ok': False, 'allowed': True, 'error': f"All backends for channel {channel.get('name')} failed: {'; '.join(errors)}"}


def _api_execute(agent_id, agent_key, url, method='GET', req_body=None, req_headers=None,
                 purpose='', workflow=False, workflow_params=None, trace_id=None, _channel_depth=0):
    """Shared sync chokepoint for the generic api_call path. Used by BOTH the
    /api/api-call endpoint (after its async Jev gate for unregistered hosts)
    and the five curated tool executors (registered services -- registration
    is the approval, so no Jev). Runs registry lookup, path/method
    enforcement, credential resolution, the metered-budget gate, header
    sanitization + server-side auth injection, then either a single request or
    the registry's workflow sequence. Builds, redacts, and wraps the
    model-facing text and accrues spend. Returns a result dict; never raises
    for a blocked or failed request."""
    _ensure_api_services_fresh()
    parsed = urllib.parse.urlparse(url)
    service = _api_service_for_host(parsed.hostname)
    registered = service is not None
    req_headers = dict(req_headers or {})

    if parsed.scheme not in ('http', 'https') or not parsed.hostname:
        return {'ok': False, 'allowed': False, 'reason': 'Only http/https URLs are allowed.'}
    if not _is_safe_public_host(parsed.hostname):
        return {'ok': False, 'allowed': False, 'reason': 'That address resolves to a private or internal network location and cannot be reached.'}

    # Channel routing: an unregistered host that a curated channel owns (e.g.
    # reddit.com) is fetched through the channel's ordered backend chain instead
    # of a plain direct GET -- the channel is a transport improvement, never a
    # bypass (the host is still SSRF-gated here and Jev-gated in the endpoint).
    if not registered and _channel_depth == 0:
        channel = _api_channel_for_host(parsed.hostname)
        if channel is not None:
            return _api_channel_execute(agent_id, agent_key, channel, url, method, req_headers, req_body, purpose, trace_id, _channel_depth)


    token = token2 = None
    if registered:
        # In workflow mode the actual submitted path lives in the registry's
        # workflow spec (the base URL alone carries no path, e.g. Higgsfield),
        # so enforce path rules only for plain (non-workflow) calls.
        is_workflow = bool(workflow) and bool((service or {}).get('workflow'))
        if not is_workflow and not _api_service_path_allowed(service, method, parsed.path):
            return {'ok': False, 'allowed': False, 'reason': 'That path/method is not in the registered service\'s allowed rules.'}
        token, token2, cred_error = _api_credential_value(service)
        if cred_error:
            return {'ok': False, 'allowed': False, 'reason': f'Service credential unavailable: {cred_error}'}
    else:
        if method not in ('GET', 'HEAD'):
            return {'ok': False, 'allowed': False, 'reason': 'Write access is only available for hosts in the registered-services list. Use GET/HEAD for unregistered hosts.'}

    spend_kind = (service or {}).get('spend') or {}
    if spend_kind.get('kind') == 'apify' and _apify_budget_exceeded():
        return {'ok': False, 'allowed': False, 'reason': 'The Apify monthly budget is spent. Do not retry; runs are refused until next month.'}
    if _api_daily_calls_exceeded(service):
        return {'ok': False, 'allowed': False, 'reason': 'The daily call budget for this service is spent. Do not retry until the quota refills.'}

    # Sanitize first (strip auth-ish agent headers), then inject registry
    # credential + default headers server-side.
    for h in ('authorization', 'cookie', 'host'):
        req_headers.pop(h, None)
    req_headers = {k: v for k, v in req_headers.items() if k.lower() in ('accept', 'accept-language', 'user-agent')}
    # The allowlist above strips any caller-supplied content-type, and a dict
    # body is sent as JSON -- so say so explicitly. Services like Tavily 422 a
    # JSON body sent without the header (confirmed live: HTTP 422
    # "Input should be a valid dictionary or object to extract fields from").
    if req_body is not None and not any(h.lower() == 'content-type' for h in req_headers):
        req_headers['Content-Type'] = 'application/json'
    if registered and token is not None:
        try:
            url, req_headers, req_body = _api_apply_auth(service, token, token2, method, url, req_headers, req_body)
        except Exception as e:
            # Auth injection can fail (e.g. the OAuth2 token mint refused or the
            # endpoint errored). The request must NOT go out unauthenticated --
            # fail cleanly, same shape as a blocked request.
            return {'ok': False, 'allowed': True, 'error': f'Approved, but auth could not be applied: {e}'}
    for hdr_name, hdr_value in ((service or {}).get('default_headers') or {}).items():
        req_headers.setdefault(hdr_name, hdr_value)

    if workflow and (service or {}).get('workflow'):
        try:
            wf = _api_execute_workflow(service, spend_kind, url, method, req_headers, req_body, workflow_params, agent_id=agent_id)
        except Exception as e:
            return {'ok': False, 'allowed': True, 'error': f'Approved, but the workflow failed: {e}'}
        parsed_json, ctype, wrapped, instruction = _api_build_text(
            {'body': json.dumps(wf['data']) if wf['data'] is not None else '', 'contentType': wf.get('contentType', 'application/json'),
             'truncated': False, 'status': 200, 'finalUrl': url}, service, True, parsed.hostname)
        return {'ok': True, 'allowed': True, 'textForModel': wrapped, 'modelInstruction': instruction,
                'status': 200, 'service': (service or {}).get('name'), 'data': wf['data'], 'wrapped_json': wrapped,
                'ids': wf.get('ids') or {}, 'usd': wf.get('usd'), 'finalUrl': url}

    try:
        result = _api_request_sync(method, url, req_headers, req_body)
    except Exception as e:
        return {'ok': False, 'allowed': True, 'error': f'Approved, but the request failed: {e}'}

    parsed_json, ctype, wrapped, instruction = _api_build_text(result, service, registered, parsed.hostname)
    _api_accrue(spend_kind, ctype, parsed_json)
    _api_accrue_daily_call(service)
    return {'ok': True, 'allowed': True, 'textForModel': wrapped, 'modelInstruction': instruction,
            'status': result['status'], 'service': (service or {}).get('name'), 'data': parsed_json, 'wrapped_json': wrapped,
            'finalUrl': result.get('finalUrl') or url}


def _api_call_response(agent_id, authorized, out, trace_id=None, url='', method='', purpose=''):
    """Map an _api_execute result dict onto the /api/api-call HTTP response,
    logging each outcome exactly once."""
    if out.get('allowed') is False:
        log_action(agent_id, 'api-call', {'url': url, 'method': method, 'purpose': purpose, 'decision': 'blocked', 'reason': out.get('reason')}, authorized=authorized, trace_id=trace_id)
        return JSONResponse({'allowed': False, 'reason': out.get('reason')})
    if out.get('ok') is False:
        log_action(agent_id, 'api-call', {'url': url, 'method': method, 'purpose': purpose, 'decision': 'allowed_but_failed', 'reason': out.get('error')}, authorized=authorized, trace_id=trace_id)
        return JSONResponse({'allowed': True, 'error': out.get('error')})
    log_action(agent_id, 'api-call', {'url': url, 'method': method, 'purpose': purpose, 'decision': 'allowed', 'status': out.get('status'), 'service': out.get('service'), 'channel': out.get('channel'), 'backend': out.get('backend')}, authorized=authorized, trace_id=trace_id)
    return JSONResponse({'allowed': True, 'textForModel': out.get('textForModel'), 'modelInstruction': out.get('modelInstruction'), 'status': out.get('status')})


# ---- api_call channels: per-channel probe (agent-reach doctor mirror) --------
# A "doctor" for the read-only channels, mirroring agent-reach's `doctor`
# command: for each channel, probe each backend in the ordered chain and report
# which backend currently answers, so the player can see what the channel is
# actually routing through today (and which backends are down). Player-only --
# it makes real outbound calls, so it must not be callable by agents.
CHANNEL_PROBE_TIMEOUT_S = 8


def _probe_backend_sync(backend, probe_url):
    """One backend probe: build the fetch URL from the channel's probe_url,
    do a lightweight GET, return {ok, status, error}. Never raises."""
    bservice_id = backend.get('service')
    bservice = _API_SERVICES.get(bservice_id)
    if not bservice:
        return {'service': bservice_id, 'ok': False, 'error': 'backend service not registered'}
    try:
        url = _api_backend_url(backend, probe_url)
    except Exception as e:
        return {'service': bservice_id, 'ok': False, 'error': f'bad url template: {e}'}
    bparsed = urllib.parse.urlparse(url)
    if bparsed.scheme not in ('http', 'https') or not bparsed.hostname or not _is_safe_public_host(bparsed.hostname):
        return {'service': bservice_id, 'ok': False, 'error': 'probe target not a safe public URL'}
    try:
        req = urllib.request.Request(url, method='GET')
        req.add_header('User-Agent', 'AIThinkTankChannelProbe/1.0')
        with _safe_urlopen(req, timeout=CHANNEL_PROBE_TIMEOUT_S) as resp:
            resp.read(4096)
            status = resp.status
        return {'service': bservice_id, 'ok': status < 500, 'status': status, 'url': url}
    except Exception as e:
        return {'service': bservice_id, 'ok': False, 'error': str(e)[:200]}


def _probe_all_channels_sync():
    """Probe every configured channel's backend chain. Returns {channel_id: {...}}
    where the first backend that answers is 'current'."""
    results = {}
    for chost, channel in sorted(_API_CHANNELS.items()):
        cid = channel.get('id') or chost
        if cid in results:
            continue
        probe_url = (channel.get('probe_url') or '').strip()
        if not probe_url:
            results[cid] = {'name': channel.get('name'), 'ok': False, 'error': 'no probe_url configured', 'backends': []}
            continue
        backends = [_probe_backend_sync(b, probe_url) for b in (channel.get('backends') or [])]
        current = next((b.get('service') for b in backends if b.get('ok')), None)
        results[cid] = {
            'name': channel.get('name'),
            'hosts': channel.get('hosts') or [],
            'probe_url': probe_url,
            'ok': current is not None,
            'current': current,
            'backends': backends,
        }
    return results


@app.get('/api/channel-probe')
async def channel_probe(request: Request):
    """Player-only doctor for the read-only channels: reports, per channel,
    which backend in the ordered chain currently answers (agent-reach's
    `doctor` mirror). Makes real outbound GETs to each backend's probe URL, so
    it is session-gated (player) and rate-limited like every other outbound
    tool -- agents never call this."""
    if not _require_player_session(request):
        return JSONResponse({'error': 'Unauthorized -- please log in'}, status_code=401)
    if not check_rate_limit('channel-probe'):
        return JSONResponse({'error': f'Rate limit exceeded -- max {RATE_LIMIT_MAX_CALLS} calls per {RATE_LIMIT_WINDOW_S}s.'}, status_code=429)
    if _API_CHANNELS_LOAD_ERROR:
        return JSONResponse({'error': f'channel registry failed to load: {_API_CHANNELS_LOAD_ERROR}'}, status_code=500)
    log_action('player', 'channel-probe', {'channels': len(_API_CHANNELS)})
    results = await asyncio.to_thread(_probe_all_channels_sync)
    return JSONResponse({'channels': results})


@app.get('/api/ais/recent')
async def ais_recent(request: Request):
    """Read the AISStream collector's buffered maritime feed (see the
    read_ais_feed tool). Any valid agent key or player session may read it --
    it is buffered, read-only, and never exposes the API key. Returns
    connection status, buffer health, and the most recent frames within the
    window."""
    agent_id = (request.query_params.get('agentId') or '').strip()
    presented = request.headers.get('X-Agent-Key') or ''
    authed = (agent_id and verify_agent_key(agent_id, presented) is True)
    if not authed:
        authed = _require_player_session(request)
    if not authed:
        return JSONResponse({'error': 'Unauthorized'}, status_code=401)
    max_msgs = max(1, min(int(request.query_params.get('max') or 20), 100))
    window_s = max(10, min(int(request.query_params.get('window_s') or 1800), 86400))
    status = _ws_status('aisstream')
    return JSONResponse({
        'ok': True,
        'connected': status.get('connected'),
        'lastError': status.get('last_error'),
        'connectedAt': status.get('connected_at'),
        'lastMessageAt': status.get('last_tick_at'),
        'frames': _ws_recent('aisstream', max_items=max_msgs, window_s=window_s),
    })


